#!/usr/bin/env node
// Writes the @volo-uti/volo-web-ui component index into ./AGENTS.md so coding agents find existing components.
// `--check` exits 1 when the block is missing or stale (run it in the product's check).
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ID = "volo-web-ui-index";
const TITLE = "Index of @volo-uti/volo-web-ui";
const INTRO =
  "Generated by volo-web-ui-index; do not edit (rerun after upgrading @volo-uti/volo-web-ui). Before writing UI, find the component here and read its doc file. Use these, not raw HTML elements or look-alike components. If nothing fits, say what you looked for first. The doc of each entry is node_modules/@volo-uti/volo-web-ui/docs/<section>/<name>.md ([.] is the docs folder itself). Compound parts and types are in each doc.";

const MAX_CHARS = 8000;
const check = process.argv.includes("--check");
const target = join(process.cwd(), "AGENTS.md");
const lines = readFileSync(
  join(dirname(fileURLToPath(import.meta.url)), "..", "docs", "index.txt"),
  "utf8",
)
  .trimEnd()
  .split("\n");

const block = [
  `<!-- BEGIN:${ID} -->`,
  "",
  `## ${TITLE}`,
  "",
  INTRO,
  "",
  "```text",
  ...lines,
  "```",
  "",
  `<!-- END:${ID} -->`,
].join("\n");

if (block.length > MAX_CHARS) {
  console.error(`${ID}: the block is ${block.length} characters; the limit is ${MAX_CHARS}`);
  process.exit(1);
}

const blockPattern = (id) => new RegExp(`<!-- BEGIN:${id} -->[\\s\\S]*?<!-- END:${id} -->`);
const pattern = blockPattern(ID);
const current = existsSync(target) ? readFileSync(target, "utf8") : "";

// A BEGIN marker without its END would make the replacement below append a second block
for (const id of [ID]) {
  const begins = current.includes(`<!-- BEGIN:${id} -->`);
  const ends = current.includes(`<!-- END:${id} -->`);
  if (begins !== ends || (begins && !blockPattern(id).test(current))) {
    console.error(
      `${ID}: AGENTS.md has an unmatched ${begins ? "BEGIN" : "END"}:${id} marker; fix or remove it`,
    );
    process.exit(1);
  }
}

const next = pattern.test(current)
  ? current.replace(pattern, () => block)
  : `${current.trimEnd()}${current ? "\n\n" : ""}${block}\n`;

if (check) {
  if (!pattern.test(current)) {
    console.error(`${ID}: AGENTS.md has no ${ID} block; run \`pnpm exec ${ID}\``);
    process.exit(1);
  }
  if (next !== current) {
    console.error(`${ID}: the block in AGENTS.md is stale; run \`pnpm exec ${ID}\``);
    process.exit(1);
  }
  console.log(`${ID}: AGENTS.md block is current`);
} else {
  writeFileSync(target, next);
  console.log(
    `${ID}: wrote ${lines.filter((l) => !l.startsWith("[")).length} entries to AGENTS.md`,
  );
}
